namespace zdb {
bool CNode::AddDI(CDI* di)
	{
		/* 0x2255c0: appended; marks the node modified and as having DI */
		if (di != NULL && !m_di.Exists(di))
		{
			di->m_refcount++;
			m_di.insert(m_di.end(), di);
			m_modified = true;
			m_hasDI = true;

			return true;
		}

		return false;
	}
}

